.pool .split-item{display:flex;flex-direction:column;gap:3px;min-width:0}
.pool .split-item small{font-size:calc(11px * var(--cj-font-scale,1));color:var(--ui-pool-muted);opacity:.92}
.pool .split-item strong{font:700 calc(15px * var(--cj-font-scale,1))/1.25 Georgia,"Noto Sans CJK SC",sans-serif;color:var(--ui-gold);letter-spacing:.3px;overflow-wrap:anywhere}
/* rc.25：资产卡片改成上标题下描述两层，右侧不再留空白列 */
.asset-tabs{display:flex;flex-wrap:wrap;gap:5px;margin:9px 0}
.asset-tabs button{border:1px solid #dee5d9;background:#fffefa;color:#6d8071;border-radius:10px;padding:6px 9px;flex:1 1 calc(25% - 5px);min-width:64px;font-size:calc(11px * var(--cj-font-scale,1))}
.asset-mini{display:flex;flex-direction:column;align-items:stretch;gap:6px;margin-bottom:8px;background:#fffdf7;border:1px solid #e6e9df;border-radius:12px;padding:11px 12px}
.asset-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;width:100%}
.asset-title{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.asset-title b{font-size:calc(13px * var(--cj-font-scale,1));line-height:1.35}
.asset-description{margin:0;width:100%;line-height:1.65;overflow-wrap:anywhere}
/* rc.25：经历与底线之间加一条分隔线 */
.limit-sep{border-top:1px dashed var(--ui-line);margin:7px 0}

/* rc.27：三套主题的扩展语义色（樱粉/魅紫/翠绿/暖金） */
:root{
  --ui-plum-bg:#f4eef8;--ui-plum:#734085;--ui-plum-border:#dcc7e3;
  --ui-green-bg:#e8f3e7;--ui-green:#3b6e4c;--ui-green-border:#c5dcc8;
  --ui-amber-bg:#fdf3df;--ui-amber:#965a1e;--ui-amber-border:#ebd1a7;
}
.theme-gold{
  --ui-plum-bg:#f6edf8;--ui-plum:#7b3b8c;--ui-plum-border:#dfc5e6;
  --ui-green-bg:#eaf5ec;--ui-green:#387049;--ui-green-border:#c3dec8;
  --ui-amber-bg:#fff4df;--ui-amber:#9c5718;--ui-amber-border:#ebd0a0;
}
.theme-purple{
  --ui-plum-bg:#412954;--ui-plum:#e4b8ff;--ui-plum-border:#6d488a;
  --ui-green-bg:#243d35;--ui-green:#9fe3b8;--ui-green-border:#3d695a;
  --ui-amber-bg:#473522;--ui-amber:#ffd596;--ui-amber-border:#785937;
}

/* rc.27：365px 窄屏女性信息分层样式 */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
.chips{display:flex;flex-wrap:wrap;gap:5px;margin:4px 0 8px}
.chip-tag{display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;font-size:calc(10px * var(--cj-font-scale,1));font-weight:700;border:1px solid var(--ui-line);background:var(--ui-soft);color:var(--ui-strong);line-height:1.4}
.chip-pink{background:var(--ui-pink-bg);color:var(--ui-pink);border-color:var(--ui-pink-border)}
.chip-plum{background:var(--ui-plum-bg);color:var(--ui-plum);border-color:var(--ui-plum-border)}
.chip-green{background:var(--ui-green-bg);color:var(--ui-green);border-color:var(--ui-green-border)}
.chip-amber{background:var(--ui-amber-bg);color:var(--ui-amber);border-color:var(--ui-amber-border)}

.mini-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:6px 0 8px}
.mini-stat{background:var(--ui-card2);border:1px solid var(--ui-line);border-radius:10px;padding:5px 6px;text-align:center}
.mini-stat small{display:block;font-size:calc(9.5px * var(--cj-font-scale,1));color:var(--ui-sub);line-height:1.2}
.mini-stat b{font-size:calc(11px * var(--cj-font-scale,1));color:var(--ui-ink)}

.kv{display:grid;grid-template-columns:8.2em minmax(0,1fr);gap:7px;padding:5.5px 0;border-bottom:1px dashed var(--ui-line);align-items:baseline;font-size:calc(11px * var(--cj-font-scale,1));line-height:1.6}
.kv:last-child{border-bottom:0;padding-bottom:0}
.kv-k{color:var(--ui-sub);font-size:calc(10.5px * var(--cj-font-scale,1));font-weight:600;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis}
.kv-v{color:var(--ui-ink);min-width:0;overflow-wrap:anywhere}
.kv-v b{color:var(--ui-strong);font-weight:700}
.kv-v b.hl-pink{color:var(--ui-pink)}
.kv-v b.hl-plum{color:var(--ui-plum)}
.kv-v b.hl-strong{color:var(--ui-strong)}

.thought-card{border-left:3px solid var(--ui-pink);background:var(--ui-pink-bg);border-radius:9px;padding:7px 9px;margin:6px 0;color:var(--ui-ink)!important}
.goal-card{border-left:3px solid var(--ui-accent);background:var(--ui-soft);border-radius:9px;padding:7px 9px;margin-top:7px;color:var(--ui-ink)!important;font-weight:600}
.dream-card{border-left:3px solid var(--ui-amber);background:var(--ui-amber-bg);border-radius:9px;padding:7px 9px;margin-top:6px;color:var(--ui-ink)!important;font-weight:600}

.limit-cell{display:flex;align-items:center;justify-content:space-between;gap:4px;padding:4.5px 7px;border-radius:8px;border:1px solid var(--ui-line);background:var(--ui-card2);font-size:calc(10.5px * var(--cj-font-scale,1));white-space:nowrap}
.limit-cell.locked{opacity:.52;background:transparent}
.limit-badge{font-size:calc(9.5px * var(--cj-font-scale,1));font-weight:700;padding:1px 6px;border-radius:6px;color:var(--ui-sub)}

/* rc.27：固定正文底部模式的折叠态横条 */
.folded.folded-bar{width:calc(100% - 4px)!important;height:48px!important;margin:2px!important;padding:0 14px!important;border-radius:14px!important;border-width:2px!important;flex-direction:row!important;justify-content:space-between!important;align-items:center!important;cursor:pointer!important}
.folded-bar-left,.folded-bar-right{display:flex;align-items:center;gap:8px;min-width:0}
.folded-bar-left b{font-size:calc(13px * var(--cj-font-scale,1));white-space:nowrap}
.folded-bar-left small{font-size:calc(10.5px * var(--cj-font-scale,1));opacity:.88;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.folded-bar-right{flex-shrink:0;position:relative}
.folded-bar-right b{font-size:calc(12.5px * var(--cj-font-scale,1))}
.folded-bar-right small{font-size:calc(10px * var(--cj-font-scale,1));opacity:.85}

/* rc.28：固定正文底部 · 100% 满宽内嵌宽屏面板模式（脱掉手机外壳与刘海） */
body.is-bottom-dock{overflow:visible!important}
.phone.is-bottom-dock{
  height:auto!important;min-height:0!important;max-height:none!important;
  border:1px solid var(--ui-line)!important;border-radius:16px!important;
  box-shadow:0 8px 26px var(--ui-shadow)!important;
  background:var(--ui-surface)!important;
}
.phone.is-bottom-dock::before{display:none!important}
.phone.is-bottom-dock .phone-hd{
  height:auto!important;min-height:48px!important;padding:10px 16px!important;
  border-bottom:1px solid var(--ui-line);cursor:default!important;
  flex-wrap:wrap;gap:10px;
}
.phone.is-bottom-dock .phone-screen{
  flex:none!important;height:auto!important;max-height:none!important;
  overflow:visible!important;padding:14px 16px 18px!important;
}
.phone.is-bottom-dock .bottom{display:none!important}

/* rc.28：顶栏一体化导航（宽屏底部模式独有） */
.wide-nav{display:none}
.phone.is-bottom-dock .wide-nav{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:0 auto}
.phone.is-bottom-dock .wide-tab{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--ui-line);background:var(--ui-soft);color:var(--ui-sub);border-radius:999px;padding:5px 13px;font-size:calc(12px * var(--cj-font-scale,1));font-weight:700;line-height:1.5}
.phone.is-bottom-dock .wide-tab .i{font-size:calc(14px * var(--cj-font-scale,1));line-height:1}
.phone.is-bottom-dock .wide-tab.active{background:var(--ui-accent);border-color:var(--ui-accent);color:var(--ui-accent-text)}

/* rc.28：宽屏多列舒展 */
.women-grid{display:grid;grid-template-columns:minmax(0,1fr)}
.phone.is-bottom-dock .women-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 10px}
@media(min-width:520px){
  .phone.is-bottom-dock .dossier-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .phone.is-bottom-dock .limit-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .phone.is-bottom-dock .mine-section[data-mine-section="assets"] .asset-mini{display:inline-flex;width:calc(50% - 5px);vertical-align:top;margin-right:5px}
}

/* rc.28 修复：长标签不再压到右侧数值（标签列随字号自适应 + 底线格禁止溢出） */
.kv-v{min-width:0}
.limit-cell>span{min-width:0;overflow:hidden;text-overflow:ellipsis}
.limit-cell .limit-badge{flex-shrink:0}

/* ===== rc.36：五页导航、轮盘页三盘入口、财富页钱包 ===== */
.phone .bottom{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:2px;padding:6px 4px 8px;min-height:62px}
.phone .tab{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:0;padding:4px 2px;border:none;background:transparent;white-space:nowrap;line-height:1.2;font-size:calc(10px * var(--cj-font-scale,1))}
.phone .tab .i{font-size:calc(15px * var(--cj-font-scale,1));line-height:1.1}
.phone.is-bottom-dock .wide-nav{justify-content:center;gap:5px;flex-wrap:wrap}
.phone.is-bottom-dock .wide-tab{padding:4px 10px;white-space:nowrap}
.wheel-wallet{margin-bottom:10px}
.wheel-wallet-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.wheel-wallet-row>div{display:flex;flex-direction:column;gap:2px}
.wheel-wallet-row small{color:var(--ui-sub);font-size:calc(9.5px * var(--cj-font-scale,1))}
.wheel-wallet-row b{font:calc(17px * var(--cj-font-scale,1)) Georgia,serif;color:var(--ui-gold,var(--ui-accent))}
.wheel-hub-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:9px;margin-bottom:12px}
@media(min-width:600px){.phone.is-bottom-dock .wheel-hub-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
.wheel-card{display:flex;flex-direction:column;gap:4px;width:100%;text-align:left;padding:12px;border-radius:16px;border:1px solid var(--ui-line);background:linear-gradient(150deg,var(--ui-card),var(--ui-card2,#f6f8f4));color:var(--ui-ink);cursor:pointer;box-shadow:0 3px 12px var(--ui-shadow)}
.wheel-card:hover{border-color:var(--ui-accent)}
.wheel-card-head{display:flex;align-items:center;justify-content:space-between;gap:6px}
.wheel-card-head b{font-size:calc(13px * var(--cj-font-scale,1))}
.wheel-card-badge{flex:0 0 auto;font-size:calc(9px * var(--cj-font-scale,1));padding:2px 7px;border-radius:999px;border:1px solid var(--ui-tag-border);background:var(--ui-tag-bg);color:var(--ui-tag-text);font-weight:700}
.wheel-card small{color:var(--ui-sub);font-size:calc(10px * var(--cj-font-scale,1));line-height:1.5}
.wheel-card-meta{color:var(--ui-sub);font-size:calc(9.5px * var(--cj-font-scale,1));line-height:1.5}
.wheel-card-note{color:var(--ui-sub);font-size:calc(9px * var(--cj-font-scale,1));line-height:1.45;opacity:.8}
.wheel-card-cta{margin-top:3px;font-size:calc(11px * var(--cj-font-scale,1));font-weight:800;color:var(--ui-accent)}
.wheel-card-wish{background:linear-gradient(150deg,var(--ui-card),var(--ui-soft))}
.wheel-card-casino{background:linear-gradient(150deg,var(--ui-card),var(--ui-card2,#f6f8f4))}
.ability-shop-link{margin-top:7px}
.toylink-banner{display:flex;align-items:center;justify-content:space-between;gap:10px}
.toylink-banner b{font-size:calc(12px * var(--cj-font-scale,1))}
.toylink-banner small{display:block;color:var(--ui-sub);font-size:calc(9.5px * var(--cj-font-scale,1));margin-top:2px}
.shop-buy{flex:0 0 auto}

.bag-list{display:grid;gap:6px;max-height:320px;overflow:auto}
.bag-row{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;border:1px solid var(--ui-line);background:var(--ui-card)}
.bag-row b{font-size:calc(11.5px * var(--cj-font-scale,1))}
.bag-row small{display:block;color:var(--ui-sub);font-size:calc(9.5px * var(--cj-font-scale,1))}
.bag-row .bag-actions{display:flex;gap:5px;flex:0 0 auto}
.shop-list{display:grid;gap:6px;max-height:340px;overflow:auto}
.shop-row{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;border:1px solid var(--ui-line);background:var(--ui-card)}
.shop-row b{font-size:calc(11.5px * var(--cj-font-scale,1))}
.shop-row small{display:block;color:var(--ui-sub);font-size:calc(9.5px * var(--cj-font-scale,1));line-height:1.4}
.shop-price{flex:0 0 auto;font-size:calc(10px * var(--cj-font-scale,1));color:var(--ui-accent);font-weight:700}

/* 轮盘落点金光（无指针，用格子高亮指示） */
.wheel-svg .cell.lit{stroke:#fff6d8;stroke-width:2.6;filter:drop-shadow(0 0 12px rgba(247,214,138,.95))}
.wheel-svg .ring{transform-box:view-box}
/* ===== rc.37：三页信息架构 / 星愿卡册 / 分类切换 / 折叠条高度账 ===== */
:root{--rarity-gray:#8f98a8;--rarity-red:#e0607c;--rarity-gold:#e6be6a;--rarity-rainbow:#c79bf0}
.overlay{background:rgba(10,12,14,.72)}
.modal-close{width:30px;height:30px;padding:0;border:0;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--ui-soft);color:var(--ui-ink);font-size:calc(18px * var(--cj-font-scale,1));line-height:1;flex-shrink:0}
.modal-close span{display:block;line-height:1;transform:translateY(-.5px)}

.seg-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:3px;margin:0 0 10px;border-radius:12px;background:var(--ui-soft);border:1px solid var(--ui-line)}
.seg-tab{border:0;border-radius:9px;padding:6px 4px;background:transparent;color:var(--ui-sub);font-weight:600;font-size:calc(11px * var(--cj-font-scale,1));line-height:1.2;display:inline-flex;align-items:center;justify-content:center;gap:4px;white-space:nowrap;cursor:pointer}
.seg-tab.on{background:var(--ui-card);color:var(--ui-ink);box-shadow:0 1px 4px var(--ui-shadow)}

.wheel-topbar{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 11px;margin-bottom:10px;border-radius:14px;background:var(--ui-card);border:1px solid var(--ui-line)}
.wheel-topbar-stats{display:flex;align-items:baseline;gap:10px;min-width:0;flex-wrap:wrap}
.wheel-topbar-stats b{font:700 calc(14px * var(--cj-font-scale,1))/1 Georgia,serif;color:var(--ui-gold,var(--ui-accent))}
.wheel-topbar-acts{display:flex;gap:6px;flex-shrink:0}
.wheel-card{padding:12px 13px;border-radius:14px;gap:6px;border:1px solid var(--ui-line)}

.binder-bar{display:flex;justify-content:space-between;gap:8px;margin:0 0 8px;font-size:calc(10px * var(--cj-font-scale,1));color:var(--ui-sub)}
.card-binder-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.phone.is-bottom-dock .card-binder-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.wish-card{position:relative;aspect-ratio:5/7;border-radius:12px;padding:7px 8px;display:flex;flex-direction:column;justify-content:space-between;border:1.5px solid var(--wc-rim,#8f98a8);background:linear-gradient(160deg,var(--wc-t1,#1e212a),var(--wc-t2,#2a2e3a));color:#f4ecdc;overflow:hidden;contain:layout paint}
.wish-card::before{content:"";position:absolute;inset:3px;border-radius:9px;border:1px solid var(--wc-halo,rgba(143,152,168,.3));pointer-events:none}
.wc-top{display:flex;align-items:center;gap:4px;font-size:calc(7.5px * var(--cj-font-scale,1));letter-spacing:.06em;color:rgba(244,236,220,.82)}
.wc-tier{font-weight:700;color:var(--wc-rim,#8f98a8)}
.wc-pool{padding:0 4px;border-radius:999px;border:1px solid var(--wc-halo,rgba(143,152,168,.3));font-size:calc(7px * var(--cj-font-scale,1))}
.wc-serial{margin-left:auto;font-size:calc(7px * var(--cj-font-scale,1));opacity:.8}
.wc-mid{display:grid;place-items:center;color:var(--wc-rim);min-height:0}
.wish-glyph{width:46%;height:auto;max-height:40%}
.wc-bot{display:flex;flex-direction:column;gap:1px;min-width:0}
.wc-name{font-size:calc(10.5px * var(--cj-font-scale,1));letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wc-motto{font-size:calc(7.5px * var(--cj-font-scale,1));line-height:1.35;color:rgba(244,236,220,.7);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.wc-points{font:700 calc(12.5px * var(--cj-font-scale,1))/1.1 Georgia,serif;color:var(--wc-rim)}
.wc-streak{position:absolute;left:6px;top:22%;font-size:calc(7.5px * var(--cj-font-scale,1));padding:1px 5px;border-radius:999px;background:rgba(255,120,90,.2);color:#ffcbb6}
.wc-lock{position:absolute;right:5px;bottom:5px;font-size:calc(10px * var(--cj-font-scale,1))}
.binder-item{display:flex;flex-direction:column;gap:5px;min-width:0}
.wc-acts{display:flex;gap:4px}
.wc-acts .cj-act{flex:1;min-width:0;padding:6px 2px;font-size:calc(9px * var(--cj-font-scale,1));border-radius:8px}
.wc-acts .cj-act[disabled]{opacity:.42}
.empty-card{display:flex;flex-direction:column;align-items:center;gap:8px;padding:22px 16px;border-radius:16px;border:1px dashed var(--ui-line);background:var(--ui-card);text-align:center}
.empty-card b{font-size:calc(12.5px * var(--cj-font-scale,1))}

/* 底部停靠折叠条：52 + 2×2 边框 = 56 = iframe 视口，溢出 0 */
body.is-folded-bar{overflow:hidden!important}
body.is-folded-bar #app{height:100%!important;overflow:hidden!important}
.folded.folded-bar{box-sizing:border-box!important;height:52px!important;margin:2px!important;border-width:1.5px!important}

/* ===== rc.36：轮盘页门户卡与异能栏 ===== */
.portals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 12px}
.portal{position:relative;display:flex;flex-direction:column;gap:4px;padding:12px;border-radius:14px;border:1px solid var(--ui-line);background:linear-gradient(160deg,var(--ui-card),var(--ui-soft));color:var(--ui-ink);text-align:left;cursor:pointer;box-shadow:0 2px 8px var(--ui-shadow)}
.portal:hover{border-color:var(--ui-accent)}
.portal b{font-size:calc(12.5px * var(--cj-font-scale,1));line-height:1.3}
.portal small{color:var(--ui-sub);font-size:calc(9px * var(--cj-font-scale,1));line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.portal-val{margin-top:2px;font-size:calc(10px * var(--cj-font-scale,1));font-weight:800;color:var(--ui-accent)}
.ability-card{padding:11px 12px}
.ability-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px}
.ability-head b{font-size:calc(12.5px * var(--cj-font-scale,1))}

/* ===== rc.36：背包 / 星愿商城重做（稀有度色条 + 分层信息 + 统一按钮） ===== */
.bag-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:2px 0 10px;padding:10px 12px;border-radius:14px;background:linear-gradient(150deg,var(--ui-card),var(--ui-soft));border:1px solid var(--ui-line)}
.bag-summary>div{display:flex;flex-direction:column;gap:2px;min-width:0}
.bag-summary small{color:var(--ui-sub);font-size:calc(9px * var(--cj-font-scale,1));white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bag-summary b{font:calc(16px * var(--cj-font-scale,1)) Georgia,serif;color:var(--ui-gold,var(--ui-accent))}
.bag-list{display:grid;gap:8px;max-height:50dvh;overflow:auto;padding:1px 2px 1px 1px}
.bag-item{position:relative;display:flex;gap:9px;padding:11px 12px 11px 15px;border-radius:14px;border:1px solid var(--ui-line);background:var(--ui-card);--rarity:#9aa3b5}
.bag-item[data-rarity="gray"]{--rarity:#9aa3b5}
.bag-item[data-rarity="red"]{--rarity:#e0607c}
